INSERT INTO client_releases (version, version_key, platform, file_key, file_name, size, sha256, notes, notes_en, published_at) VALUES ('2.84.1', 2084001, 'windows', 'releases/CosmicPlatformer-Setup-2.84.1.exe', 'CosmicPlatformer-Setup-2.84.1.exe', 159973268, 'abfd973250987445379d9cbaa664cb99c9e5364bba9ea2e89eba36b62aa53335', 'Version 2.84.1 :
• Raids : le temps du raid se compte à rebours (rouge dans la dernière minute) ; plus de plateformes dans les antres et l''arène du Cœur ; ouvrir le menu (Tab) en courant ne fait plus défiler ses onglets ; les Gigaboss et le Cœur rééquilibrés (environ 10 min pour un bon groupe de 8 à 3 / 5) ; la difficulté d''un événement (1 à 5) change vraiment leur vie et leurs dégâts, affichés à côté du choix (titan 13).
• Course à la vérification : chaque tentative (Solo, Duo, Trio) a de nouveau son bouton de commentaires, avec leur nombre, à côté du ▶, comme les records d''un niveau classique.
• Cadeaux : plus de limite de récompenses ni de joueurs ; « Tous les joueurs » envoie à chaque joueur actif, et un grand envoi n''apparaît qu''une fois complet, jamais en double.', 'Version 2.84.1:
• Raids: the raid''s time now counts down (red in the last minute); more platforms in the lairs and the Heart''s arena; opening the menu (Tab) while running no longer cycles its tabs; the Gigaboss and the Heart rebalanced (about 10 min for a good group of 8 at 3 / 5); an event''s difficulty (1 to 5) now really changes their health and damage, shown next to the choice (titan 13).
• Verification race: every attempt (Solo, Duo, Trio) has its comments button, with their count again, next to ▶, as on a classic level''s records.
• Gifts: no limit on rewards or players any more; « All players » sends to every active player, and a large send only appears once it is complete, never twice.', '2026-11-21T19:03:26.589Z') ON CONFLICT (version) DO NOTHING;
